// ---------- 1. Calculate stock summary ----------
const items = $input.all().map(i => i.json)
  .filter(r => String(r['Item ID'] || '').trim().startsWith('SIS'));

const num = v => Number(String(v ?? '').replace(/[,₹\s]/g, '')) || 0;

let inStockItems = 0, soldOutItems = 0, totalPieces = 0, costValue = 0, retailValue = 0;
const lowStock = [], mismatches = [];

for (const r of items) {
  const qty = num(r['Stock']);
  const status = String(r['Status'] || '').trim().toLowerCase();

  if (status === 'sold out') soldOutItems++;
  else if (status === 'in stock') inStockItems++;

  totalPieces += qty;
  costValue   += qty * num(r['Actual price']);
  retailValue += qty * num(r['Selling price']);

  if (qty === 1) lowStock.push({ id: r['Item ID'], name: r['Item name'] });
  if ((status === 'sold out' && qty > 0) || (status === 'in stock' && qty === 0)) {
    mismatches.push(`${r['Item ID']} (stock ${qty}, status "${r['Status']}")`);
  }
}

// ---------- 2. Build HTML email ----------
const inr = n => '₹' + Number(n).toLocaleString('en-IN');
const today = new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });

const card = (label, value, color) => `
  <td style="padding:12px;background:#f7f3ee;border-radius:8px;text-align:center;">
    <div style="font-size:12px;color:#666;">${label}</div>
    <div style="font-size:20px;font-weight:bold;color:${color};">${value}</div>
  </td>`;

const lowRows = lowStock.map((it, i) => `
  <tr style="background:${i % 2 ? '#fff' : '#faf7f2'};">
    <td style="padding:6px 10px;border-bottom:1px solid #eee;">${it.id}</td>
    <td style="padding:6px 10px;border-bottom:1px solid #eee;">${it.name}</td>
  </tr>`).join('');

const mismatchBlock = mismatches.length
  ? `<p style="color:#b00020;"><b>⚠ Fix these rows:</b> ${mismatches.join(', ')}</p>`
  : `<p style="color:#2e7d32;">✓ No status mismatches found.</p>`;

const html = `
<div style="font-family:Arial,sans-serif;max-width:640px;margin:auto;color:#222;">
  <h2 style="color:#8b1a1a;margin-bottom:4px;">Sri Iniya Silks – Stock Report</h2>
  <div style="color:#888;font-size:13px;margin-bottom:16px;">Silk List · ${today}</div>

  <table width="100%" cellspacing="8"><tr>
    ${card('Total Items', items.length, '#222')}
    ${card('In Stock', inStockItems, '#2e7d32')}
    ${card('Sold Out', soldOutItems, '#b00020')}
    ${card('Pieces', totalPieces, '#222')}
  </tr></table>

  <table width="100%" cellspacing="8"><tr>
    ${card('Value at Cost', inr(costValue), '#222')}
    ${card('Value at Selling Price', inr(retailValue), '#8b1a1a')}
  </tr></table>

  <h3 style="margin-top:24px;">Low Stock – only 1 piece left (${lowStock.length})</h3>
  <table width="100%" style="border-collapse:collapse;font-size:13px;">
    <tr style="background:#8b1a1a;color:#fff;">
      <th style="padding:8px 10px;text-align:left;">Item ID</th>
      <th style="padding:8px 10px;text-align:left;">Item Name</th>
    </tr>
    ${lowRows}
  </table>

  ${mismatchBlock}
</div>`;

return [{ json: { subject: `Saree Stock Report – ${today}`, html } }];
